// Боевые свойства предметов 26.1.2 — файл собирает tools/make_combat_table.py
// из отчётов штатного генератора официального сервера (только числа).
// Руками не править.

/// Модификатор атрибута, который предмет даёт по умолчанию.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct ItemMod {
    /// Номер атрибута в реестре.
    pub attribute: i32,
    /// Операция: 0 — прибавить, 1 — умножить основу, 2 — умножить итог.
    pub operation: u8,
    /// Группа мест (порядок EquipmentSlotGroup): 1 — основная рука, 4–7 — обувь…шлем.
    pub slot: u8,
    pub amount: f64,
    pub id: &'static str,
}

/// Боевые свойства одного предмета (часть полей — данные таблицы, которые
/// сервер пока не читает: имя, зачаровываемость, место и звук надевания).
#[derive(Clone, Copy, Debug)]
#[allow(dead_code)]
pub struct ItemInfo {
    pub name: &'static str,
    pub item: i32,
    pub max_damage: i32,
    pub enchantable: i32,
    pub mods: &'static [ItemMod],
    /// Есть компонент «оружие»: расход прочности за удар (0 — компонента нет).
    pub damage_per_attack: i32,
    /// Сколько секунд удар отключает щит (0 — не отключает).
    pub disable_blocking_seconds: f32,
    /// Место надевания: 0 — нет, 4 — обувь, 5 — штаны, 6 — нагрудник, 7 — шлем, 9 — тело, 2 — вторая рука.
    pub equip_slot: u8,
    /// Звук надевания.
    pub equip_sound: &'static str,
}

